export function Logo({
  variant = 'full',
  className,
  iconClassName,
  wordmarkClassName,
}: LogoProps) {
  if (variant === 'icon') {
    return <CassoIcon className={className} />;
  }

  return (
    <span
      className={cn(
        'inline-flex items-center gap-2 whitespace-nowrap',
        className,
      )}
    >
      <CassoIcon className={cn('h-8 w-8 shrink-0', iconClassName)} />
      <span
        className={cn(
          'text-lg font-bold tracking-tight text-primary',
          wordmarkClassName,
        )}
      >
        Casso AR
      </span>
    </span>
  );
}
